-- 452: Original BrillaPrep WASSCE Core Mathematics sprint 2 beta questions, part 10 of 10 (batch wassce-core-math-sprint2-001).
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_452_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_452_guard;
INSERT INTO _migration_452_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_coremath_s2_046' AND NOT (q.topic_id IS 'topic_wassce_p2_math_prb' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'A bag contains 4 white balls and 6 black balls. A ball is picked at random and replaced, then a second ball is picked. Find the probability that both balls are black.' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. 1/3","B. 9/25","C. 3/5","D. 9/20"]' AND q.correct_answer IS 'B' AND q.explanation IS 'Because the first ball is replaced, the draws are independent and P(black) = 6/10 = 3/5 each time. Hence P(both black) = (3/5) × (3/5) = 9/25. (1/3 is close to 30/90, the without-replacement value.) Therefore the correct answer is B: 9/25.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Find' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_coremath_s2_046' AND NOT (r.batch_id IS 'wassce-core-math-sprint2-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_452_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_coremath_s2_047' AND NOT (q.topic_id IS 'topic_wassce_p2_math_prb' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'The probability that it rains on a given day is 0.3. What is the probability that it does not rain on that day?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. 0.3","B. 0.6","C. 0.7","D. 1.3"]' AND q.correct_answer IS 'C' AND q.explanation IS 'Raining and not raining are complementary events whose probabilities sum to 1, so P(no rain) = 1 − 0.3 = 0.7. (1.3 is impossible: no probability can exceed 1.) Therefore the correct answer is C: 0.7.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Calculate' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_coremath_s2_047' AND NOT (r.batch_id IS 'wassce-core-math-sprint2-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_452_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_coremath_s2_048' AND NOT (q.topic_id IS 'topic_wassce_p2_math_prb' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'A number is chosen at random from the integers 1 to 20 inclusive. What is the probability that it is a multiple of 3?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. 7/20","B. 1/3","C. 1/4","D. 3/10"]' AND q.correct_answer IS 'D' AND q.explanation IS 'The multiples of 3 from 1 to 20 are 3, 6, 9, 12, 15 and 18 — six numbers — so the probability is 6/20 = 3/10. (7/20 wrongly counts 21, which is outside the range.) Therefore the correct answer is D: 3/10.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Calculate' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_coremath_s2_048' AND NOT (r.batch_id IS 'wassce-core-math-sprint2-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_coremath_s2_046', 'topic_wassce_p2_math_prb', 'subj_wassce_core_math', 'exam_wassce', NULL, NULL, 'A bag contains 4 white balls and 6 black balls. A ball is picked at random and replaced, then a second ball is picked. Find the probability that both balls are black.', 'multiple_choice', NULL, '["A. 1/3","B. 9/25","C. 3/5","D. 9/20"]', 'B', 'Because the first ball is replaced, the draws are independent and P(black) = 6/10 = 3/5 each time. Hence P(both black) = (3/5) × (3/5) = 9/25. (1/3 is close to 30/90, the without-replacement value.) Therefore the correct answer is B: 9/25.', 'medium', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Find', 'AO2', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_coremath_s2_047', 'topic_wassce_p2_math_prb', 'subj_wassce_core_math', 'exam_wassce', NULL, NULL, 'The probability that it rains on a given day is 0.3. What is the probability that it does not rain on that day?', 'multiple_choice', NULL, '["A. 0.3","B. 0.6","C. 0.7","D. 1.3"]', 'C', 'Raining and not raining are complementary events whose probabilities sum to 1, so P(no rain) = 1 − 0.3 = 0.7. (1.3 is impossible: no probability can exceed 1.) Therefore the correct answer is C: 0.7.', 'medium', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Calculate', 'AO2', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_coremath_s2_048', 'topic_wassce_p2_math_prb', 'subj_wassce_core_math', 'exam_wassce', NULL, NULL, 'A number is chosen at random from the integers 1 to 20 inclusive. What is the probability that it is a multiple of 3?', 'multiple_choice', NULL, '["A. 7/20","B. 1/3","C. 1/4","D. 3/10"]', 'D', 'The multiples of 3 from 1 to 20 are 3, 6, 9, 12, 15 and 18 — six numbers — so the probability is 6/20 = 3/10. (7/20 wrongly counts 21, which is outside the range.) Therefore the correct answer is D: 3/10.', 'medium', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Calculate', 'AO2', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT id, 'wassce-core-math-sprint2-001', 'automated_beta', 'beta', 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.', 'https://nacca.gov.gh/secondary-education-curriculum/', 0, 1 FROM questions WHERE id IN ('q_was_coremath_s2_046', 'q_was_coremath_s2_047', 'q_was_coremath_s2_048');
DELETE FROM _migration_452_guard;
INSERT INTO _migration_452_guard(valid) SELECT CASE WHEN (SELECT COUNT(*) FROM questions WHERE id IN ('q_was_coremath_s2_046', 'q_was_coremath_s2_047', 'q_was_coremath_s2_048')) = 3 AND (SELECT COUNT(*) FROM question_content_releases r WHERE r.question_id IN ('q_was_coremath_s2_046', 'q_was_coremath_s2_047', 'q_was_coremath_s2_048') AND r.batch_id IS 'wassce-core-math-sprint2-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1) = 3 THEN 1 ELSE 0 END;
DROP TABLE _migration_452_guard;
